}

[data-ui-unit="stays"] {
  display: block;
}

[data-ui-unit="stays"] #results-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
  width: 100%;
}

[data-ui-unit="stays"] .stay-card {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
}

[data-ui-unit="stays"] .stay-media {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  border-radius: 12px;
}

[data-ui-unit="stays"] .stay-photo-link {
  display: block;
  width: 100%;
  height: 100%;
}

[data-ui-unit="stays"] .stay-photo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

[data-ui-unit="stays"] .favorite {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  min-width: 44px;
  height: auto;
  border: none;
  border-radius: 999px;
  background-color: rgba(255, 255, 255, 0.8);
  color: var(--text);
  cursor: pointer;
  transition: background-color 0.1s ease, color 0.1s ease;
}

[data-ui-unit="stays"] .favorite img {
  width: 20px;
  height: 20px;
  display: block;
  fill: currentColor;
  flex-shrink: 0;
}

[data-ui-unit="stays"] .favorite span {
  font-family: "Noto Sans KR", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  white-space: nowrap;
}

[data-ui-unit="stays"] .favorite:hover {
  background-color: rgba(255, 255, 255, 1);
}

[data-ui-unit="stays"] .favorite[aria-pressed="true"] {
  color: #b42318;
}

[data-ui-unit="stays"] .stay-facts {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 12px;
  width: 100%;
}

[data-ui-unit="stays"] .stay-card h2 {
  margin: 0;
  padding: 0;
}

[data-ui-unit="stays"] .stay-card h2 a {
  font-family: "Noto Sans KR", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.5;
  color: var(--text);
  text-decoration: none;
}

[data-ui-unit="stays"] .stay-location,
[data-ui-unit="stays"] .stay-room,
[data-ui-unit="stays"] .stay-policy,
[data-ui-unit="stays"] .stay-total,
[data-ui-unit="stays"] .stay-unavailable {
  margin: 0;
  padding: 0;
  font-family: "Noto Sans KR", sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  color: var(--muted);
}

[data-ui-unit="stays"] .stay-price {
  display: flex;
  align-items: baseline;
  gap: 2px;
  margin-top: 8px;
  padding: 0;
}

[data-ui-unit="stays"] .stay-price strong {
  font-family: "Noto Sans KR", sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--text);
}

[data-ui-unit="stays"] .stay-price > span {
  font-family: "Noto Sans KR", sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  color: var(--text);
}

[data-ui-unit="navigation"] {
  display: flex;
  width: 100%;
  height: auto;
  padding: 8px 12px calc(8px + env(safe-area-inset-bottom));
  gap: 4px;
  box-sizing: border-box;
}

[data-ui-unit="navigation"] a {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 4px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--muted);
  box-sizing: border-box;
}

[data-ui-unit="navigation"] a img {
  width: 20px;
  height: 20px;
  display: block;
  margin-bottom: 4px;
}

[data-ui-unit="navigation"] a span {
  font-family: "Noto Sans KR", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  padding: 4px 8px;
  text-align: center;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: break-word;
  box-sizing: border-box;
}

[data-ui-unit="navigation"] a[aria-current="page"] {
  color: var(--action);
  position: relative;
}

[data-ui-unit="navigation"] a[aria-current="page"] span {
  font-weight: 700;
  background-color: rgba(181, 29, 81, 0.06);
  border-radius: 4px;
}




